/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataSourceEventHandler(formDataSourceStr(MarkupAutoSetup, MarkupAutoTable), FormDataSourceEventType::Activated),
 SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void MarkupAutoTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource      markupAutoTableDS = sender;
    MarkupAutoTable     markupAutoTable = sender.cursor();
    markupAutoTableDS.object(fieldNum(MarkupAutoTable,KCS_BOSCustGroup2Alliance)).enabled(markupAutoTable.AccountCode == TableGroupAll::GroupId && markupAutoTable.ModuleCategory == HeadingLine::Heading);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormDataFieldEventHandler(formDataFieldStr(MarkupAutoSetup, MarkupAutoTable, AccountCode), FormDataFieldEventType::Modified),
 SuppressBPWarning('BPParameterNotUsed', 'False positive') ]
public static void AccountCode_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource      markupAutoTableDS = sender.datasource();
    MarkupAutoTable     markupAutoTable   = markupAutoTableDS.cursor();

    if (markupAutoTable.AccountCode != TableGroupAll::GroupId)
    {
        markupAutoTable.KCS_BOSCustGroup2Alliance = NoYes::No;
    }

    markupAutoTableDS.object(fieldNum(MarkupAutoTable,KCS_BOSCustGroup2Alliance)).enabled(markupAutoTable.AccountCode == TableGroupAll::GroupId && markupAutoTable.ModuleCategory == HeadingLine::Heading);

}

