[FormDataFieldEventHandler(formDataFieldStr(MarkupAutoSetup, MarkupAutoTable, KCS_BOSCustGroup2Alliance), FormDataFieldEventType::Modified),
 SuppressBPWarning('BPParameterNotUsed', 'False positive')]
public static void AVAIsTOSRelation_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource      markupAutoTableDS = sender.datasource();
    MarkupAutoTable     markupAutoTable   = markupAutoTableDS.cursor();

    markupAutoTable.AccountRelation = '';
}
